# -*- coding: utf-8 -*-
"""Verify async provider execution remembers fallback route successes."""
from __future__ import annotations

import asyncio
import dataclasses
import json
import re
import typing

import pytest

import llm_router
from tests.llm_router.bdd import _support
from tests.llm_router.support import builders

pytestmark = pytest.mark.verification_kind("unit")


@dataclasses.dataclass
class _DummyProviderResponse:
    """Minimal response conforming to provider result expectation."""

    text: str = "ok"
    content: str = "ok"
    model: str = "test-model"
    provider: str = "test-provider"


def _create_test_router():
    """Create a router instance with at least two routes for testing fallbacks."""
    # 1. Try builder functions from support.builders
    if hasattr(builders, "build_router"):
        fn = builders.build_router
        try:
            return fn()
        except TypeError:
            pass
        for spec_candidate in (
            "primary -> fallback",
            "openai/gpt-4o -> anthropic/claude-3-5-sonnet",
            ("primary", "fallback"),
            ["primary", "fallback"],
        ):
            try:
                return fn(spec_candidate)
            except Exception:
                pass
            try:
                return fn(spec=spec_candidate)
            except Exception:
                pass

    if hasattr(builders, "build_route") and hasattr(builders, "build_router"):
        try:
            r1 = builders.build_route()
            r2 = builders.build_route()
            try:
                return builders.build_router(routes=[r1, r2])
            except Exception:
                pass
            try:
                return builders.build_router([r1, r2])
            except Exception:
                pass
        except Exception:
            pass

    # 2. Try helpers in bdd._support
    for helper_name in ("build_router", "make_router", "create_router", "get_router"):
        helper = getattr(_support, helper_name, None)
        if callable(helper):
            try:
                return helper()
            except Exception:
                pass

    # 3. Direct LLMRouter instantiation
    if hasattr(llm_router, "LLMRouter"):
        for spec_candidate in (
            "primary -> fallback",
            "openai/gpt-4o -> anthropic/claude-3-5-sonnet",
            ("primary", "fallback"),
            ["primary", "fallback"],
        ):
            try:
                return llm_router.LLMRouter(spec=spec_candidate)
            except Exception:
                pass
            try:
                return llm_router.LLMRouter(spec_candidate)
            except Exception:
                pass

    msg = "Could not instantiate a test router using available builders."
    raise RuntimeError(msg)


def _build_fake_response():
    """Construct a fake response payload using project builders or fallback dummy."""
    if hasattr(builders, "build_response"):
        try:
            return builders.build_response(text="ok")
        except Exception:
            try:
                return builders.build_response()
            except Exception:
                pass
    if hasattr(builders, "build_provider_response"):
        try:
            return builders.build_provider_response()
        except Exception:
            pass
    return _DummyProviderResponse()


@pytest.mark.verifies("REQ_ASYNC_PROVIDER_EXECUTION[revision==1]")
@pytest.mark.asyncio
async def test_async_fallback_remembers_succeeded_route(monkeypatch):
    """Pin that async routing remembers fallback success and starts next attempt there."""
    router = _create_test_router()
    runtime = getattr(router, "_runtime", router)

    # Extract primary and fallback routes from the route plan
    route_plan = runtime.route_plan
    routes = getattr(route_plan, "routes", None)
    if routes is None:
        if isinstance(route_plan, (list, tuple)):
            routes = route_plan
        else:
            routes = list(route_plan)

    assert len(routes) >= 2, "Router requires at least two routes for fallback test"
    primary_route = routes[0]
    fallback_route = routes[1]

    attempted_routes_per_call: list[list[object]] = []
    current_call_attempts: list[object] = []
    fake_response = _build_fake_response()

    # Track calls and make primary route fail, fallback succeed
    async def mock_call_async_with_timeout(request, timeout_seconds=None):
        route = getattr(request, "route", None)
        current_call_attempts.append(route)
        if route == primary_route:
            msg = "Simulated primary route failure"
            raise RuntimeError(msg)
        return fake_response

    monkeypatch.setattr(runtime, "_call_async_with_timeout", mock_call_async_with_timeout)

    # First async call: primary route fails, fallback route succeeds
    current_call_attempts = []
    res1 = await router.aquery("Test prompt 1")
    attempted_routes_per_call.append(list(current_call_attempts))

    assert attempted_routes_per_call[0] == [primary_route, fallback_route], (
        "Call 1 should have attempted primary first (failed) and fallback second (succeeded)"
    )

    # Second async call: sticky start should prioritize the remembered fallback route
    current_call_attempts = []
    res2 = await router.aquery("Test prompt 2")
    attempted_routes_per_call.append(list(current_call_attempts))

    # Verification: check sticky index on runtime
    assert runtime._sticky_start_route_index is not None, (
        "Expected _sticky_start_route_index to be set after fallback success in _run_async"
    )

    # Verification: check that call 2 tried fallback route first
    assert attempted_routes_per_call[1][0] == fallback_route, (
        f"Call 2 should have tried remembered fallback route {fallback_route} first, "
        f"got {attempted_routes_per_call[1][0]}"
    )

    # Verification: check traces on response 2
    traces = getattr(res2, "routing_traces", None)
    if traces is None:
        traces = getattr(res2, "traces", None)
    if traces is None and hasattr(res2, "final_trace"):
        traces = [res2.final_trace]

    assert traces, "Response 2 should contain routing traces"
    first_trace = traces[0]
    trace_route = getattr(first_trace, "route", None)
    assert trace_route == fallback_route, (
        f"First trace on subsequent async call should be fallback route {fallback_route}, "
        f"got {trace_route}"
    )
